  if(!committed)throw Error('Photo budget contention');const submit=now();if(!(submit instanceof Date)||!Number.isFinite(submit.getTime())||submit.getTime()>=Date.parse(pricing.validUntil)||submit.toISOString().slice(0,7)!==month)return {status:'needs_recovery',attemptId};let value,receipt;try{const response=await requestModel({model:pricing.model,instruction:VISUAL_AUDIT_PROMPT,bytes,mimeType});value=output(response.output);receipt=response.receipt;if(!receipt||typeof receipt.requestId!=='string'||!receipt.requestId||receipt.requestId.length>200||receipt.model!==pricing.model||receipt.finishReason!=='stop'||!Number.isSafeInteger(receipt.inputTokens)||receipt.inputTokens<0||!Number.isSafeInteger(receipt.outputTokens)||receipt.outputTokens<0||receipt.outputTokens>1024)throw Error('Invalid provider receipt');}catch(e){const allowed=['provider_auth','provider_rate_limit','provider_server','provider_rejected','provider_timeout','provider_network','provider_invalid_json'];return {status:'needs_recovery',attemptId,diagnostic:allowed.includes(e?.diagnostic)?e.diagnostic:'invalid_provider_result',retryAfter:typeof e?.retryAfter==='string'&&e.retryAfter.length<=80?e.retryAfter:null};}
